struct hash<std::pair<T1, T2>> {
    size_t operator()(const std::pair<T1, T2> &p) const noexcept {
        auto h1 = std::hash<T1>{}(p.first);
        auto h2 = std::hash<T2>{}(p.second);
        return h1 ^ (h2 << 1);
    }
};

