        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
        for (const auto &nodeWeak : nodes) {
            if (auto node = nodeWeak.lock()) {
                m_activeBatchNodes[node].insert(batchId);
            }
        }
        m_activeBatchIds.insert(batchId);
    }

