TEST(ExpressionOperatorsTest, TestOperatorsInBatchOperations) {
    using namespace reaction;

    auto x = var(10).setName("x");
    auto y = var(5).setName("y");
    auto result = expr((x > y) && (x / y == 2)).setName("result");

